/* SDK8/9 typed texture creation/storage and sampling acceptance. */
typedef struct TCContext{TCDevice*d;HMODULE module;UINT mode;BOOL core;}TCContext;
static HRESULT tc_create(TCContext*,UINT,UINT,UINT,DWORD,UINT,UINT,TCTexture**);
static void tc_size(TCContext*,TCSurface*,UINT);
static void tc_sampler(TCContext*);
static HRESULT tc_fvf(TCDevice*);
static HRESULT tc_bind(TCContext*,TCTexture*);
static void tc_read(TCContext*);
static HRESULT tc_reset(TCContext*);
static void tc_check(BOOL ok,const char*s){if(!ok){tc_report(s);ExitProcess(1);}}
static void tc_expect(HRESULT hr,const char*s){tc_check(SUCCEEDED(hr),s);}
static void tc_metadata(TCContext*c,TCTexture*t,UINT level,UINT format,UINT width,UINT height,UINT bytes){TCSurface*s=NULL,*again=NULL;tc_expect(TC_SURFACE(t,level,&s),"FAIL texture surface");tc_expect(TC_SURFACE(t,level,&again),"FAIL repeated texture surface");tc_check(s==again,"FAIL texture surface identity");TCDevice*parent=NULL;tc_expect(TC_PARENT(s,&parent),"FAIL texture parent");tc_check(parent==c->d,"FAIL texture device identity");TC_DREL(parent);TCDesc desc;tc_expect(TC_DESC(s,&desc),"FAIL texture descriptor");tc_check(desc.Format==format&&desc.Width==width&&desc.Height==height&&desc.Type==1&&!desc.MultiSampleType,"FAIL texture metadata fields");tc_size(c,s,bytes);TC_SREL(again);TC_SREL(s);}
static void tc_capture(TCContext*c,UINT step){struct TVertex{float x,y,z,w;DWORD color;float u,v;};const struct TVertex vertices[6]={{-.5f,-.5f,.5f,1,0xffffffff,0,0},{7.5f,-.5f,.5f,1,0xffffffff,1,0},{-.5f,7.5f,.5f,1,0xffffffff,0,1},{-.5f,7.5f,.5f,1,0xffffffff,0,1},{7.5f,-.5f,.5f,1,0xffffffff,1,0},{7.5f,7.5f,.5f,1,0xffffffff,1,1}};tc_expect(TC_CLEAR(c->d,0,NULL,1,0xff010203,1,0),"FAIL texture clear");tc_expect(TC_BEGIN(c->d),"FAIL texture scene");tc_expect(TC_DRAW(c->d,D3DPT_TRIANGLELIST,2,vertices,sizeof(vertices[0])),"FAIL texture sample");tc_expect(TC_END(c->d),"FAIL texture end scene");tc_read(c);char line[160];wsprintfA(line,"TEXCORE FRAME index=%u mode=%u step=%u readback=1",tc_frame_index++,c->mode,step);tc_report(line);}
static void tc_cases(TCContext*c){
 tc_expect(TC_RS(c->d,D3DRS_ZENABLE,FALSE),"FAIL texture Z");tc_expect(TC_RS(c->d,D3DRS_LIGHTING,FALSE),"FAIL texture lighting");tc_expect(TC_RS(c->d,D3DRS_CULLMODE,D3DCULL_NONE),"FAIL texture cull");tc_expect(tc_fvf(c->d),"FAIL texture FVF");tc_expect(TC_TSS(c->d,0,D3DTSS_COLOROP,D3DTOP_SELECTARG1),"FAIL texture op");tc_expect(TC_TSS(c->d,0,D3DTSS_COLORARG1,D3DTA_TEXTURE),"FAIL texture argument");tc_expect(TC_TSS(c->d,0,D3DTSS_ALPHAOP,D3DTOP_SELECTARG1),"FAIL texture alpha");tc_expect(TC_TSS(c->d,0,D3DTSS_ALPHAARG1,D3DTA_TEXTURE),"FAIL texture alpha argument");tc_sampler(c);
 UINT invalid=0;if(c->mode!=2){for(UINT n=0;n<11;n++){UINT w=n==0?0:n==1?4097:8,h=n==2?0:n==3?4097:8,levels=n==4?99:n==8?0:1,usage=n==5?2:n==8||n==9?1:0,format=n==7?113:21,pool=n==6?4:n==9?1:0;TCTexture*out=(void*)99;tc_check(tc_create(c,w,h,levels,usage,format,pool,n==10?NULL:&out)==D3DERR_INVALIDCALL&&(n==10?out==(void*)99:out==NULL),"FAIL API8 texture invalid/output");invalid++;}}
 TCTexture*t=NULL;D3DLOCKED_RECT lock;
 if(c->mode==2){t=(void*)99;tc_check(tc_create(c,3,2,0,0,65,1,&t)==D3DERR_INVALIDCALL&&t==NULL,"FAIL ordinary9 texture65 refusal");}else{
  tc_expect(tc_create(c,3,2,0,0,65,1,&t),"FAIL API8 texture65 create");tc_check(TC_LEVELS(t)==2,"FAIL texture65 mip count");for(UINT l=0;l<2;l++){UINT w=l?1:3,h=l?1:2;tc_metadata(c,t,l,65,w,h,w*h*4);tc_expect(TC_LOCK(t,l,&lock,NULL,0),"FAIL texture65 lock");tc_check(lock.Pitch==(INT)(w*4),"FAIL texture65 pitch");for(UINT y=0;y<h;y++)for(UINT x=0;x<w;x++){DWORD*p=(DWORD*)((BYTE*)lock.pBits+y*lock.Pitch);tc_check(!p[x],"FAIL texture65 initial zero");p[x]=0x12340000u|(l<<12)|(y<<8)|x;}tc_expect(TC_UNLOCK(t,l),"FAIL texture65 upload");tc_expect(TC_LOCK(t,l,&lock,NULL,16),"FAIL texture65 readonly");for(UINT y=0;y<h;y++)for(UINT x=0;x<w;x++)tc_check(((DWORD*)((BYTE*)lock.pBits+y*lock.Pitch))[x]==(0x12340000u|(l<<12)|(y<<8)|x),"FAIL texture65 preserved bits");tc_expect(TC_UNLOCK(t,l),"FAIL texture65 readonly unlock");}tc_check(!TC_TREL(t),"FAIL texture65 refs");}
 tc_expect(tc_create(c,8,8,0,0,21,1,&t),"FAIL main texture create");tc_check(TC_LEVELS(t)==4,"FAIL main full mip count");for(UINT l=0;l<4;l++){UINT w=8u>>l;tc_metadata(c,t,l,21,w,w,w*w*4);tc_expect(TC_LOCK(t,l,&lock,NULL,0),"FAIL main mip lock");tc_check(lock.Pitch==(INT)(w*4),"FAIL main mip pitch");for(UINT y=0;y<w;y++)for(UINT x=0;x<w;x++){DWORD*p=(DWORD*)((BYTE*)lock.pBits+y*lock.Pitch);tc_check(!p[x],"FAIL main zero storage");p[x]=l?0xff00ff00:0xffff0000;}tc_expect(TC_UNLOCK(t,l),"FAIL main mip upload");}
 tc_expect(tc_bind(c,t),"FAIL main texture bind");tc_capture(c,0);
 RECT area={2,2,6,6};tc_expect(TC_LOCK(t,0,&lock,&area,0),"FAIL partial texture lock");tc_check(lock.Pitch==32,"FAIL partial texture whole pitch");for(UINT y=0;y<4;y++)for(UINT x=0;x<4;x++)((DWORD*)((BYTE*)lock.pBits+y*lock.Pitch))[x]=0xff0000ff;tc_expect(TC_UNLOCK(t,0),"FAIL partial texture upload");tc_capture(c,1);
 TCSurface*s=NULL;tc_expect(TC_SURFACE(t,0,&s),"FAIL surface upload view");area=(RECT){6,0,8,8};tc_expect(TC_SLOCK(s,&lock,&area,0),"FAIL surface child lock");tc_check(lock.Pitch==32,"FAIL surface child pitch");for(UINT y=0;y<8;y++)for(UINT x=0;x<2;x++)((DWORD*)((BYTE*)lock.pBits+y*lock.Pitch))[x]=0xff00ff00;tc_expect(TC_SUNLOCK(s),"FAIL surface child upload");TC_SREL(s);tc_capture(c,2);tc_expect(tc_bind(c,NULL),"FAIL main unbind");tc_check(!TC_TREL(t),"FAIL main texture refs");
 tc_expect(tc_create(c,4,4,1,0,827611204u,1,&t),"FAIL BC1 texture");tc_metadata(c,t,0,827611204u,4,4,8);tc_expect(TC_LOCK(t,0,&lock,NULL,0),"FAIL BC1 lock");tc_check(lock.Pitch==8,"FAIL BC1 pitch");BYTE*bits=lock.pBits;const BYTE blue[8]={31,0,0,0,0,0,0,0};for(UINT n=0;n<8;n++){tc_check(!bits[n],"FAIL BC1 zero storage");bits[n]=blue[n];}tc_expect(TC_UNLOCK(t,0),"FAIL BC1 upload");tc_expect(tc_bind(c,t),"FAIL BC1 bind");tc_capture(c,3);tc_expect(tc_bind(c,NULL),"FAIL BC1 unbind");tc_check(!TC_TREL(t),"FAIL BC1 refs");
 tc_expect(tc_reset(c),"FAIL texture Reset");char line[220];wsprintfA(line,"TEXCORE CHECK mode=%u invalidCases=%u cpu65=%u mipLevels=4 partialPitch=32 surfaceIdentity=1 BC1=1 reset=1 finalRefs=0",c->mode,invalid,c->mode!=2);tc_report(line);
}
